---@class CameraInputCN

local CameraInputCN = {}

------------ lifeCycle ------------
function CameraInputCN:Awake()
    self._vcam = nil
    
    self._onSwipeActionEvent = nil
    
    if self:IsWindowsPlatform() then
        self._raycastResultCache = nil
        self._behaviourAction = nil
        self._onUpdate = nil
        self._controlMode = nil
    end
end

function CameraInputCN:OnDestroy()
    self._vcam = nil
    
    self:UnlistenSwipeInput()
    self:ClearSwipeInput()
    
    if self:IsWindowsPlatform() then
        self._raycastResultCache:Clear()
        self._raycastResultCache = nil

        if not isNull(self._behaviourAction) then
            self._behaviourAction.UpdateAction = nil
        end 
        self._behaviourAction = nil
        self._onUpdate = nil
        self._controlMode = nil

        self:ShowMouse()
    end
end

function CameraInputCN:Start()
    self._vcam = KTool.GetComponent(self.controller.gameObject, CinemachineFreeLook)
    local vcamCollider = KTool.GetComponent(self.controller.gameObject, CinemachineCollider)

    self:InitCinemachineParam(self._vcam, vcamCollider)
    self:InitSwipeInput()
    
    if self:IsWindowsPlatform() then
        self._raycastResultCache = support.new_list(RaycastResult)

        --- 注册update函数
        self._onUpdate = Bind(self, self.Update)
        self._behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, BehaviourAction)
        
        self:SetControlMode(Constants.CameraControlMode.MoveMouse)
    else
        self:ListenSwipeInput()
    end
end

function CameraInputCN:Update()

    --- 现在update里面的逻辑只服务于window平台

    if Cursor.lockState == CursorLockMode.Locked then
        local xInput = Input.GetAxis(CameraInputXAxisName)
        local yInput = Input.GetAxis(CameraInputYAxisName)
        self:SetAxisValue(0, xInput)
        self:SetAxisValue(1, yInput)
    else
        self:ClearCameraInputAxisValue()
    end

    if Input.GetKeyDown(KeyCode.LeftAlt) then
        self:ShowMouse()
    end

    if Input.GetKeyUp(KeyCode.LeftAlt) then
        self:HideMouse()
    end
end
