------------ Windows ------------
--- 显示鼠标
function CameraInputCN:ShowMouse()
    Cursor.lockState = CursorLockMode.None
    ScreenTouchEffectModule.Instance:Show()
end

--- 隐藏鼠标
function CameraInputCN:HideMouse()
    Cursor.lockState = CursorLockMode.Locked
    ScreenTouchEffectModule.Instance:Hide()
end

--- 设置虚拟相机的控制模式
---@param mode Constants.CameraControlMode
function CameraInputCN:SetControlMode(mode)
    if not self:IsWindowsPlatform() then
        return
    end
    if mode ~= Constants.CameraControlMode.DragMouse then
        self:UnlistenSwipeInput()
    end
    if mode ~= Constants.CameraControlMode.MoveMouse then
        self:UnlistenUpdate()
        self:ShowMouse()
    end

    if mode == Constants.CameraControlMode.DragMouse then
        self:ListenSwipeInput()
    elseif mode == Constants.CameraControlMode.MoveMouse then
        self:ListenUpdate()
        self:HideMouse()
    end

    self._controlMode = mode

    -- 切换相机模式的时候清理一下输入值，防止切换模式以后相机卡在最后一个输入值上一直转动
    self:ClearCameraInputAxisValue()
end

function CameraInputCN:ListenUpdate()
    self._behaviourAction.UpdateAction = self._onUpdate
end

function CameraInputCN:UnlistenUpdate()
    self._behaviourAction.UpdateAction = nil
end
