--- 设置虚拟相机目标
---@param followTarget UnityEngine.Transform
---@param lookAtTarget UnityEngine.Transform
function CameraInputCN:SetTarget(followTarget, lookAtTarget)
    if isNull(self._vcam) then
        self._vcam = KTool.GetComponent(self.controller.gameObject, CinemachineFreeLook)
    end
    self._vcam.Follow = followTarget
    self._vcam.LookAt = lookAtTarget
end
--- SetAxisValue
---@param axis integer
---@param value number
function CameraInputCN:SetAxisValue(axis, value)
    if axis == 0 then
        local xAxis = self._vcam.m_XAxis
        xAxis.m_InputAxisValue = value
        self._vcam.m_XAxis = xAxis
    elseif axis == 1 then
        local yAxis = self._vcam.m_YAxis
        yAxis.m_InputAxisValue = value
        self._vcam.m_YAxis = yAxis
    end
end

function CameraInputCN:IsWindowsPlatform()
    if tonumber(IsActiveControlJoystick) == 1 then
        return false
    end
    return GameUtils.IsPCPlatform()
end

