--- 清理滑屏输入控制
function CameraInputCN:ClearSwipeInput()
    EasyTouch.instance.alwaysSendSwipe = false
    
    self._onSwipeActionEvent = nil
end

--- 监听滑屏输入事件
function CameraInputCN:ListenSwipeInput()
    Events.AddListener(Constants.EventNames.OnQuickSwipe2FingerAction, self._onSwipeActionEvent)
end

--- 不监听滑屏输入事件 
function CameraInputCN:UnlistenSwipeInput()
    Events.RemoveListener(Constants.EventNames.OnQuickSwipe2FingerAction, self._onSwipeActionEvent)
end

---OnSwipeActionEvent
---@param gesture HedgehogTeam.EasyTouch.Gesture
function CameraInputCN:OnSwipeActionEvent(gesture)
    if isNull(self._vcam) then return end
    if gesture then
        if gesture.type == EasyTouch.EvtType.On_Swipe then
            -- x max 250
            -- y max 150
            self:SetAxisValue(0, gesture.deltaPosition.x)
            self:SetAxisValue(1, gesture.deltaPosition.y)
        elseif gesture.type == EasyTouch.EvtType.On_SwipeEnd then
            self:ClearCameraInputAxisValue()
        end
    end
end

--- 清理相机转动的输入值
function CameraInputCN:ClearCameraInputAxisValue()
    self:SetAxisValue(0, 0)
    self:SetAxisValue(1, 0)
end

--- 初始化相机参数
---@param vcam Cinemachine.CinemachineFreeLook @ 虚拟相机
---@param vcamBlender Cinemachine.CinemachineCollider @ 虚拟相机切换管理
function CameraInputCN:InitCinemachineParam(vcam, vcamCollider)
    local mainCamera = URPCameraController.Instance.mainCamera
    local brain = KTool.GetComponent(mainCamera.gameObject, typeof(CS.Cinemachine.CinemachineBrain))
    brain.m_UpdateMethod = CS.Cinemachine.CinemachineBrain.UpdateMethod.LateUpdate

    self._vcam.m_BindingMode = CS.Cinemachine.CinemachineOrbitalTransposer.BindingMode.WorldSpace
    
    if self:IsWindowsPlatform() then
        local xAxis = self._vcam.m_XAxis
        xAxis.m_MaxSpeed = 1
        xAxis.m_AccelTime = 0.1
        xAxis.m_DecelTime = 0.1
        xAxis.m_SpeedMode = CS.Cinemachine.AxisState.SpeedMode.InputValueGain
        self._vcam.m_XAxis = xAxis
        local yAxis = self._vcam.m_YAxis
        yAxis.m_MaxSpeed = 0.01
        yAxis.m_AccelTime = 0.2
        yAxis.m_DecelTime = 0.1
        yAxis.m_SpeedMode = CS.Cinemachine.AxisState.SpeedMode.InputValueGain
        self._vcam.m_YAxis = yAxis

        for i = 0, 2 do
            local rig = self._vcam:GetRig(i)
            local composer = rig:GetCinemachineComponent(Aim)
            if not isNull(composer) then
                composer.m_HorizontalDamping = 0.5
                composer.m_VerticalDamping = 0.1
            end
        end
    else
        local xAxis = self._vcam.m_XAxis
        xAxis.m_MaxSpeed = 0.12
        xAxis.m_AccelTime = 0.1
        xAxis.m_DecelTime = 0.1
        xAxis.m_SpeedMode = CS.Cinemachine.AxisState.SpeedMode.InputValueGain
        self._vcam.m_XAxis = xAxis
        local yAxis = self._vcam.m_YAxis
        yAxis.m_MaxSpeed = 0.0008
        yAxis.m_AccelTime = 0.03
        yAxis.m_DecelTime = 0.1
        yAxis.m_SpeedMode = CS.Cinemachine.AxisState.SpeedMode.InputValueGain   -- y轴卡顿，或许换一个速度模式会好？
        self._vcam.m_YAxis = yAxis

        for i = 0, 2 do
            local rig = self._vcam:GetRig(i)
            local composer = rig:GetCinemachineComponent(Aim)
            if not isNull(composer) then
                composer.m_HorizontalDamping = 0.5
                composer.m_VerticalDamping = 0.03
            end
        end
    end

    vcamCollider.m_Damping = 2
    vcamCollider.m_DampingWhenOccluded = 0.5
end
